def get_objects(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    objects = {}

    def dfs(r, c, val):
        if r < 0 or r >= h or c < 0 or c >= w or grid[r][c] != val or (r,c) in visited:
            return
        visited.add((r,c))
        objects.setdefault(val, []).append((r,c))
        dfs(r+1, c, val)
        dfs(r-1, c, val)
        dfs(r, c+1, val)
        dfs(r, c-1, val)

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r,c) not in visited:
                dfs(r,c,grid[r][c])

    return objects

