def get_components_8conn(grid):
    """Get 8-connected components using iterative DFS"""
    h, w = len(grid), len(grid[0])
    visited = set()
    components = {}

    def dfs(start, val):
        comp = []
        stack = [start]
        while stack:
            r, c = stack.pop()
            if (r,c) in visited or grid[r][c] != val:
                continue
            visited.add((r,c))
            comp.append((r,c))
            # Check all 8 neighbors
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited and grid[nr][nc] == val:
                        stack.append((nr, nc))
        return comp

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r,c) not in visited:
                comp = dfs((r,c), grid[r][c])
                components.setdefault(grid[r][c], []).append(comp)
    return components

