            rr, cc = stack.pop()
            if (rr, cc) in visited or grid[rr][cc] != color:
                continue
            visited.add((rr, cc))
            comp.append((rr, cc))
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited and grid[nr][nc] == color:
